import assert from 'node:assert/strict';
import { spawn, execFileSync } from 'node:child_process';
import { mkdir, writeFile, mkdtemp, open, readFile, chmod } from 'node:fs/promises';
import path from 'node:path';
import { NectarService } from '../../dist/service.js';
import { daemonHello, callDaemon } from '../../dist/control.js';
import { spawnDetached, stopEnvGroup, pidAlive, readProcessIdentity } from '../../dist/commands.js';
const root = path.resolve(process.argv[2] ?? `test/fixtures/.runs/legacy-${Date.now()}`);
await mkdir(root, { recursive: true });
const tailscale = path.join(root, 'tailscale');
await writeFile(tailscale, `#!${process.execPath}
const args=process.argv.slice(2);
if(args[0]==='status')console.log(JSON.stringify({BackendState:'Running',Self:{DNSName:'fixture.tailtest.ts.net.'}}));
else if(args[0]==='serve'&&args[1]==='status')console.log('{}');
`);
await chmod(tailscale, 0o700);
process.env.NECTAR_TAILSCALE_BIN = tailscale;
process.env.NECTAR_TAILSCALE_SOCKET = path.join(root, 'absent.sock');
const state = path.join(root, 'state');
process.env.NECTAR_HOME = state;
process.env.NECTAR_SOCKET = path.join(await mkdtemp('/tmp/nectar-t20-'), 'control.sock');
const service = new NectarService(state);
await service.store.init();
await service.store.writeConfig({ ...await service.store.readConfig(), upstream_port_start: 29100, upstream_port_end: 29299, tailnet_port_start: 29300, tailnet_port_end: 29499, pack_server_port: 29099 });
const repo = path.join(root, 'repo');
await mkdir(repo);
const git = (...args) => execFileSync('git', args, { cwd: repo, stdio: 'pipe' });
git('init', '-b', 'main'); git('config', 'user.email', 'fixture@example.invalid'); git('config', 'user.name', 'Fixture');
await writeFile(path.join(repo, 'nectar.toml'), 'name = "legacy"\n[web]\nserve = "exec node server.mjs"\nready_timeout = "5s"\n');
await writeFile(path.join(repo, 'server.mjs'), 'import http from "node:http";http.createServer((q,r)=>r.end("fixture")).listen(Number(process.env.PORT),"127.0.0.1");');
git('add', '.'); git('commit', '-m', 'Fixture');
const log = await open(path.join(root, 'daemon.log'), 'a');
const daemon = spawn(process.execPath, ['dist/cli.js', 'daemon', 'run', '--interval', '1h', '--gc-interval', '1h'], { env: process.env, stdio: ['ignore', log.fd, log.fd] });
const retry = async fn => { for (let i = 0; ; i++) { try { return await fn(); } catch (e) { if (e.code !== 'E_BUSY' || !e.details?.lock || i >= 100) throw e; await new Promise(r => setTimeout(r, 50)); } } };
const call = (op, args) => retry(() => callDaemon(process.env.NECTAR_SOCKET, op, { nectar_home: state, caller: {}, args }));
const update = (name, fn) => retry(() => service.store.updateEnv(name, fn));
const records = [];
let decoy;
let shellIdentity;
const say = value => console.log(JSON.stringify(value));
const publish = async branch => { git('branch', branch); const p = await call('publish', { path: repo, branch, mode: 'web', local: true }); let r = await service.store.readEnv(p.env); assert.equal(await (await fetch(r.urls.local)).text(), 'fixture'); r = await service.store.readEnv(p.env); assert(r.serve.pid > 1); records.push(r); return r; };
try {
  for (let i = 0; ; i++) { if ((await daemonHello())?.pid === daemon.pid) break; assert(i < 100, 'daemon timeout'); await new Promise(r => setTimeout(r, 100)); }
  say({ isolatedDaemon: daemon.pid, root });
  const owned = await publish('owned');
  await update(owned.name, r => { delete r.serve.start_time; });
  const doctor = await service.doctor({ noDaemon: true });
  await call('stop', { env: owned.name });
  assert.equal(doctor.checks.find(c => c.name === 'process-ownership').details.find(d => d.env === owned.name).action, 'adoptable');
  assert.equal((await service.store.readEnv(owned.name)).serve.start_time, owned.serve.start_time);
  assert(!pidAlive(owned.serve.pid));
  say({ legacyOwned: 'adopted identity persisted and stopped normally' });
  await new Promise(r => setTimeout(r, 1_100));
  const cmd = "trap 'wait; exit' TERM; sleep 300 & wait";
  const shell = spawn('/bin/sh', ['-c', cmd], { cwd: owned.worktree, detached: true, stdio: 'ignore' });
  shellIdentity = { pid: shell.pid, ...readProcessIdentity(shell.pid) };
  assert(shellIdentity.start_time);
  const original = await service.store.readEnv(owned.name);
  const injectShell = async overrides => update(owned.name, r => { Object.assign(r, original, overrides); r.status = 'publishing'; r.serve = { cmd, pid: shell.pid, pgid: shell.pid }; });
  await injectShell({ published_at: new Date(Date.now() + 60_000).toISOString(), last_touched_at: new Date(Date.now() + 60_000).toISOString() });
  await assert.rejects(call('stop', { env: owned.name }), /OS start time/); assert(pidAlive(shell.pid));
  await injectShell({ worktree: root });
  await assert.rejects(call('stop', { env: owned.name }), /cwd differs/); assert(pidAlive(shell.pid));
  await injectShell({});
  await update(owned.name, r => { r.serve.cmd = 'different command'; });
  await assert.rejects(call('stop', { env: owned.name }), /argv do not match/); assert(pidAlive(shell.pid));
  await injectShell({});
  await call('stop', { env: owned.name });
  assert.equal((await service.store.readEnv(owned.name)).serve.start_time, shellIdentity.start_time);
  assert(!pidAlive(shell.pid));
  say({ exactArgv: 'adopted without daemon parent', refusals: 'newer record timestamp, wrong cwd, wrong argv; process remained alive until verified stop' });
  const wrong = await publish('decoy');
  await call('stop', { env: wrong.name });
  decoy = spawnDetached('exec sleep 300', root, process.env, path.join(root, 'decoy.log'));
  await update(wrong.name, r => { r.status = 'publishing'; r.serve = { ...wrong.serve, ...decoy }; delete r.serve.start_time; });
  await assert.rejects(call('stop', { env: wrong.name }), /ownership unknown/);
  assert(pidAlive(decoy.pid));
  const refusedDoctor = await service.doctor({ noDaemon: true });
  assert.equal(refusedDoctor.checks.find(c => c.name === 'process-ownership').details.find(d => d.env === wrong.name).action, 'detach');
  const detached = await call('rm', { env: wrong.name, detach: true });
  assert.equal(detached.pgid, decoy.pgid); assert(pidAlive(decoy.pid));
  const audit = JSON.parse(await readFile(detached.audit_path, 'utf8'));
  assert.equal(audit.status, 'stale'); assert.equal(audit.record.serve.pid, decoy.pid);
  assert(!await service.store.maybeEnv(wrong.name));
  const republished = await call('publish', { path: repo, branch: 'decoy', mode: 'web', local: true });
  assert.equal(republished.env, wrong.name);
  const live = await service.store.readEnv(wrong.name); records.push(live);
  assert.equal(await (await fetch(live.urls.local)).text(), 'fixture');
  assert(pidAlive(decoy.pid));
  say({ decoy: 'refused and never killed', detach: detached, republish: 'HTTP 200 fixture' });
  const dead = await publish('dead');
  await call('stop', { env: dead.name });
  await update(dead.name, r => { r.status = 'publishing'; delete r.serve.start_time; });
  await call('ls', {});
  assert.equal((await service.store.readEnv(dead.name)).status, 'stopped');
  say({ deadPublishing: 'automatically stopped', PASS: true });
} finally {
  for (const r of records.reverse()) { const current = await service.store.maybeEnv(r.name); if (decoy && current?.serve?.pid === decoy.pid) await update(r.name, x => { x.serve = r.serve; }); await service.stop(r.name).catch(() => {}); }
  if (decoy) await stopEnvGroup(decoy);
  if (shellIdentity && pidAlive(shellIdentity.pid)) await stopEnvGroup(shellIdentity);
  daemon.kill('SIGTERM'); await new Promise(resolve => daemon.once('exit', resolve)); await log.close();
}
